/* ─── Helpers ─── */

function nextAttemptFromState(state: MapBootstrapState): number {
  if (state.phase === 'idle') return 1;
  return state.attempt + 1;
}

function phaseMessage(state: MapBootstrapState): string {
  switch (state.phase) {
    case 'idle':    return 'Preparing startup checks.';
    case 'loading': return `Loading ${state.currentPhase} contract from ${state.endpoint}.`;
    case 'ready':   return 'CampusNav map is ready for visitor navigation.';
    case 'error':   return state.message;
  }
}

function formatMetric(value: number): string {
  return Number.isFinite(value) ? value.toFixed(2) : '0';
}

/**
 * Find the nearest node on a given floor to a reference position.
 * Used when floor changes to snap user to nearest accessible node.
 */
function findNearestNodeOnFloor(
  graph: NormalizedNavGraph,
  floorId: number,
  fromPosition: { x: number; y: number },
): string | null {
  let nearestId: string | null = null;
  let nearestDist = Infinity;

  for (const [nodeId, record] of graph.nodeById) {
    if (record.floorId !== floorId) continue;
    const dx = record.node.x - fromPosition.x;
    const dy = record.node.y - fromPosition.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < nearestDist) {
      nearestDist = dist;
      nearestId = nodeId;
    }
  }

  return nearestId;
}

