import { describe, expect, it, vi } from 'vitest';
import * as React from 'react';
import { render, screen } from '@testing-library/react-native';
import { LiveGuidanceOverlay } from './LiveGuidanceOverlay';
import type {
  ConfidenceLevel,
  GuidancePhase,
  GuidanceState,
} from '../../routing/guidanceState';

